CREATE TABLE "ClockSession"("id" UUID NOT NULL,"companyId" UUID NOT NULL,"userId" UUID NOT NULL,"worksiteId" UUID,"startedAt" TIMESTAMPTZ(6) NOT NULL,"stoppedAt" TIMESTAMPTZ(6),"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClockSession_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "ClockSession_active_user" ON "ClockSession"("companyId","userId") WHERE "stoppedAt" IS NULL; CREATE INDEX "ClockSession_companyId_userId_idx" ON "ClockSession"("companyId","userId"); ALTER TABLE "ClockSession" ADD FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "ClockSession" ADD FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "ClockSession" ADD FOREIGN KEY("worksiteId") REFERENCES "Worksite"("id") ON DELETE SET NULL; ALTER TABLE "ClockSession" ENABLE ROW LEVEL SECURITY; ALTER TABLE "ClockSession" FORCE ROW LEVEL SECURITY; CREATE POLICY "clock_tenant" ON "ClockSession" FOR ALL USING("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid);